"use client";
/* Gulp, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Gulp(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("gulp"); }, []);
  return React.createElement("piix-pal", { "pal": "gulp", ...piixAttrs(props) });
}

export default Gulp;
